import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xfr16')
from h import P
P(7,[
(6144849,"Sucettes glacées de fruits au yaourt","Vous pouvez préparer cette recette avec n'importe quel fruit et n'importe quel parfum de yaourt. Essayez des morceaux de mangue avec du yaourt à l'ananas, ou des moitiés de kiwi avec du yaourt à la fraise. Vous pouvez aussi essayer d'autres garnitures comme de la noix de coco ou des vermicelles en sucre à la place des noix de pécan.","6","2 sucettes",
["1/4 tasse de noix de pécan (hachées)","12 bâtonnets à sucettes","1/2 tasse de yaourt grec aux myrtilles (sans matières grasses)","12 fraises entières (équeutées)","1 feuille de papier ciré"],
["Recouvrez une petite plaque de cuisson de papier ciré. Réservez.","Enfoncez les bâtonnets à sucettes dans la partie supérieure des fraises. Ne percez pas jusqu'à l'autre extrémité de la fraise.","Trempez chaque fraise dans le yaourt en secouant pour que chaque fraise soit recouverte d'une fine couche. Aidez-vous d'une cuillère pour enrober les fraises si nécessaire.","Parsemez chaque fraise enrobée de 1 cuillère à café de noix de pécan.","Placez les sucettes de fraises sur la plaque et congelez 1 à 2 heures, ou jusqu'à ce que le yaourt soit congelé. Une fois les sucettes congelées, retirez-les du papier ciré et servez, ou placez-les dans un sac de congélation à fermeture zip."],[],[]),
(6145161,"Bâtonnets de carottes fraîches","Informations nutritionnelles pour les bâtonnets de carottes","1","1 tasse",["1 tasse de carottes (coupées en bâtonnets)"],[],[],[]),
(6145357,"Hauts de cuisse de poulet grillés au jalapeño et à la pêche avec salade crémeuse d'avocat et d'artichaut","Apportez un goût d'été à votre table avec ces plats savoureux qui s'intègrent au régime à très faible teneur en glucides. Ce plat est un mélange parfait de saveurs sucrées, épicées et crémeuses, ce qui en fait un repas délicieux pour toutes les occasions.","4","6 oz de poulet, ½ tasse de pêches/piments, 2 tasses de salade",
["1 1/2 lb de hauts de cuisse de poulet désossés et sans peau","1/2 cuillère à café de poivre noir","2 cuillères à café d'huile d'olive","2 petites pêches (coupées en deux, dénoyautées et tranchées)","2 piments jalapeño entiers (épépinés et coupés en petits dés)","1 citron entier (zeste et jus)","1 cuillère à soupe de sirop de type érable sans sucre","1 gousse d'ail (hachée finement)","2 cuillères à soupe de yaourt grec nature sans matières grasses","1 cuillère à soupe de vinaigre de cidre de pomme","1 cuillère à café de moutarde de Dijon","1 cuillère à café de basilic séché","4 oz de cœurs d'artichauts marinés (égouttés et tranchés)","1/2 avocat entier (coupé en deux, dénoyauté et tranché)","5 oz de mesclun"],
["Préchauffez le four à 400 degrés F.","Épongez les hauts de cuisse de poulet avec du papier absorbant. Assaisonnez les deux côtés de poivre.","Faites chauffer une grande poêle allant au four à feu moyen-vif. Ajoutez l'huile d'olive et faites tourner pour enduire. Placez le poulet dans la poêle et saisissez-le d'un côté jusqu'à ce qu'il soit doré, environ 5 à 6 minutes. Retournez le poulet, puis retirez la poêle du feu.","Disposez les tranches de pêche et les jalapeños en dés autour du poulet dans la poêle.","Arrosez de jus de citron, de zeste et de sirop sans sucre. Transférez la poêle au four et faites cuire 15 à 18 minutes, ou jusqu'à ce que le poulet soit complètement cuit (température interne de 165 degrés F).","Pendant ce temps, dans un bol moyen, fouettez ensemble l'ail haché, la mayonnaise, le vinaigre de cidre de pomme, la moutarde de Dijon et le basilic séché.","Ajoutez les cœurs d'artichauts tranchés et l'avocat dans le bol avec la vinaigrette. Mélangez délicatement pour enrober. Ajoutez le mesclun et mélangez de nouveau.","Répartissez la salade dans les assiettes. Garnissez de poulet rôti et de pêches caramélisées."],[],[]),
(6145617,"Quinoa aux poivrons rouges","Savourez cette salade de céréales et de haricots, parfaite avec des plats principaux simples à base de protéines au dîner, et encore meilleure au déjeuner du lendemain.","5","2/3 tasse",
["1/2 tasse de quinoa tricolore","1 tasse d'eau","1/4 tasse d'oignon(s) (haché(s))","2 gousses d'ail (hachées finement)","1 poivron rouge entier (haché)","2 cuillères à café d'huile d'olive","2 tasses de chou frisé (haché)","1/3 tasse de haricots cannellini (égouttés et rincés)","1/3 tasse de noix","1 cuillère à soupe de jus de citron","1 cuillère à soupe de vinaigre balsamique"],
["Faites cuire le quinoa dans l'eau selon les instructions du paquet, sans ajouter de sel.","Pendant la cuisson du quinoa, faites sauter l'oignon, l'ail et le poivron rouge à feu moyen-vif dans l'huile d'olive pendant environ 10 minutes. Ajoutez le chou frisé et les haricots et continuez à faire sauter jusqu'à ce que le chou frisé soit flétri, environ 5 minutes de plus.","Incorporez au quinoa le mélange de poivrons, les noix, le vin (ou le jus de citron) et le vinaigre balsamique. Servez chaud ou froid."],[],[]),
(6146081,"Pétoncles géants poêlés avec carottes en spirales et oignons caramélisés","Les pétoncles sont une protéine très maigre, mais moelleuse et au goût beurré, parfaite pour une occasion spéciale. Le secret est de les saisir rapidement à feu vif.","4","1/3 tasse de pâtes + 1 tasse de mélange de carottes et de pétoncles",
["1 lb de pétoncles géants","1/4 cuillère à café de poivre noir","1 cuillère à soupe d'huile d'olive (répartie)","1 gros oignon (finement tranché)","2 gousses d'ail (hachées finement)","2 grosses carottes (coupées en spirales (ou épluchées à l'économe ou taillées en julienne à la mandoline))","1 cuillère à soupe de vinaigre de vin blanc","1 cuillère à soupe de ciboulette fraîche (hachée finement)","1 1/3 tasse de pâtes complètes ou multicéréales (cuites)"],
["Retirez la languette de chaque pétoncle, si nécessaire. La « languette » est un muscle latéral qui peut rester attaché au pétoncle. Elle ressemble à une petite languette et est plus dure que le pétoncle lui-même. Si la languette est encore attachée, tirez doucement pour la retirer.","Épongez les pétoncles avec du papier absorbant. Assaisonnez les deux côtés de poivre.","Versez 1 1/2 cuillère à café d'huile d'olive dans une sauteuse antiadhésive à feu vif.","Saisissez les pétoncles des deux côtés jusqu'à ce qu'ils soient tout juste cuits, environ deux minutes de chaque côté. Retirez de la poêle et réservez.","Ajoutez le reste de l'huile d'olive dans la poêle et réduisez à feu moyen. Ajoutez l'oignon et faites sauter jusqu'à ce qu'il soit caramélisé, environ cinq minutes.","Ajoutez l'ail et les carottes et faites sauter trois minutes. Ajoutez le vinaigre et faites cuire jusqu'à ce que tout le liquide soit réduit.","Ajoutez les pétoncles et leur jus accumulé aux légumes et faites sauter trois minutes pour terminer la cuisson des pétoncles.","Incorporez la ciboulette. Servez 1 tasse du mélange de pétoncles sur 1/3 tasse de pâtes de blé entier."],[],[]),
(6146598,"Soupe italienne tomate-basilic","Cette soupe simple est la compagne parfaite d'un sandwich au fromage grillé ou d'une salade fraîche. Mais ce n'est pas tout ! Servez-la sur des pâtes comme sauce marinara maison sans sucre ajouté (ajoutez de l'ail et du piment rouge broyé pour plus de caractère) ou servez-la froide comme accompagnement rafraîchissant d'été.","4","1 tasse",
["2 cuillères à café d'huile d'olive","1 petit oignon rouge (en dés)","1 boîte (28 oz) de purée de tomates sans sel ajouté","1 tasse de bouillon de légumes à faible teneur en sodium","1/4 cuillère à café de sel","1/3 tasse de feuilles de basilic frais (finement tranchées)","2 cuillères à café de vinaigre balsamique"],
["Faites chauffer l'huile dans une grande casserole à feu moyen. Ajoutez l'oignon et faites cuire en remuant de temps en temps jusqu'à ce qu'il soit complètement ramolli, environ 8 minutes.","Ajoutez la purée de tomates, le bouillon et le sel, et portez à ébullition à feu vif. Réduisez à feu moyen-doux et laissez mijoter à découvert jusqu'à ce que les saveurs se mélangent, environ 5 minutes. (Astuce : pour une soupe plus fluide, ajoutez un filet de bouillon.) Incorporez le basilic et le vinaigre.","Servez à la louche dans des bols. Servez chaud ou froid."],[],[]),
(6146820,"Pâtes végétariennes au chou frisé","Ces pâtes végétariennes en une seule poêle nécessitent des émiettés végétaux à base de soja qui offrent la même texture et la même saveur que le bœuf haché. Vous pouvez aussi rendre ce plat végétalien en utilisant un yaourt non laitier. Tout cuit ensemble dans une seule poêle, ce qui rend le nettoyage très facile, parfait pour un repas de semaine !","6","1 ⅓ tasse",
["1 cuillère à soupe d'huile d'olive","1 tasse d'oignon en dés","12 oz d'émiettés de « bœuf » haché sans viande (du rayon des surgelés)","1/3 tasse d'eau","2 cuillères à café d'assaisonnement italien","1 cuillère à café de flocons de piment rouge","4 tasses de bouillon de légumes à faible teneur en sodium (utilisation répartie)","8 oz de pâtes papillon de blé entier (sèches)","2 tasses de chou frisé (haché)","6 cuillères à soupe de yaourt grec nature sans matières grasses"],
["Faites chauffer l'huile d'olive dans une grande poêle à feu moyen. Faites sauter l'oignon jusqu'à ce qu'il soit tendre.","Incorporez les émiettés végétaux, l'eau et l'assaisonnement italien. Couvrez et faites cuire jusqu'à ce que les émiettés soient bien cuits, environ 4 minutes.","Versez 2 1/2 tasses de bouillon de légumes dans le mélange et portez à ébullition. Ajoutez les pâtes et faites cuire, en remuant de temps en temps, à feu moyen-vif jusqu'à ce que le bouillon soit absorbé, environ 10 à 12 minutes.","Ajoutez le reste du bouillon, le chou frisé et les flocons de piment et faites cuire à feu moyen jusqu'à ce que les pâtes soient cuites, environ 14 minutes.","Retirez la poêle du feu et incorporez le yaourt grec. Servez chaud."],[],[]),
(6147388,"Tilapia croustillant aux noix de pécan","Ce plat léger de tilapia tendre a un joli croquant et fait un excellent plat principal pour la Saint-Valentin ou n'importe quel autre jour du mois !","2","3 onces",
["2 cuillères à soupe de semoule de maïs jaune","2 cuillères à soupe de panko ou de chapelure sèche nature","1 cuillère à café de fécule de maïs","1/2 cuillère à café de poivre au citron (sans sel)","2 tilapias (environ 4 onces chacun, rincés et séchés)","2 cuillères à café de jus de citron frais","2 cuillères à soupe de noix de pécan (grossièrement hachées, grillées à sec)","1 cuillère à soupe de persil italien (plat) frais (ciselé)"],
["Préchauffez le gril du four. Vaporisez légèrement un moule de 11 x 7 x 2 pouces d'aérosol de cuisson.","Dans un plat peu profond, mélangez la semoule de maïs, le panko, la fécule de maïs et le poivre au citron. Ajoutez le poisson en le retournant pour l'enrober, en secouant l'excédent. Transférez dans le moule. Vaporisez légèrement les deux côtés du poisson d'aérosol de cuisson.","Faites gratiner 3 à 4 minutes de chaque côté, ou jusqu'à ce que le poisson s'effeuille facilement à la fourchette. Transférez dans des assiettes. Arrosez de jus de citron. Parsemez de noix de pécan et de persil."],[],[]),
(6149233,"Salade de betteraves rôties et de poulet au fromage de chèvre","Pour gagner du temps, vous pouvez utiliser la poitrine d'un poulet rôti du supermarché pour préparer cette recette.","4","1 salade",
["1 pulvérisation, 0,25 g d'aérosol de cuisson antiadhésif","4 petites betteraves","12 oz de poitrines de poulet désossées et sans peau","1/4 cuillère à café de poivre noir","1/4 tasse de vinaigre balsamique","1 cuillère à soupe d'huile d'olive","2 cuillères à soupe de bouillon de légumes à faible teneur en sodium","1 cuillère à soupe de miel ou 2 sachets d'édulcorant artificiel","2 cuillères à café de moutarde de Dijon","1 gousse d'ail (hachée finement ou râpée)","8 tasses de mélange de salade mesclun","2 cuillères à soupe de fromage de chèvre émietté","1/3 tasse d'amandes effilées (grillées)"],
["Préchauffez le four à 375 degrés F. Graissez une plaque de cuisson avec l'aérosol de cuisson. Réservez.","Enveloppez les betteraves dans du papier d'aluminium et placez-les sur la plaque de cuisson. Disposez les poitrines de poulet sur la plaque à côté des betteraves. Vaporisez le poulet d'aérosol de cuisson et assaisonnez-le de sel (facultatif) et de poivre noir. Faites rôtir le poulet et les betteraves 25 à 30 minutes, ou jusqu'à ce que la température interne du poulet atteigne 165 degrés F. Sortez les poitrines de poulet du four et réservez. Une fois légèrement refroidies, coupez le poulet en fines tranches.","Poursuivez la cuisson des betteraves jusqu'à ce qu'elles soient tendres, encore 15 à 20 minutes. Sortez les betteraves du four et réservez.","Une fois les betteraves refroidies, retirez la peau et coupez chaque betterave en morceaux de 1/2 pouce.","Dans un bol moyen, fouettez ensemble le vinaigre balsamique, l'huile d'olive, le bouillon de légumes, le miel, la moutarde de Dijon et l'ail.","Mettez la roquette et les morceaux de betterave dans un grand bol. Versez la vinaigrette sur la salade et mélangez pour enrober.","Répartissez la salade dans 4 assiettes. Garnissez chaque salade de 1/4 des tranches de poitrine de poulet, de 1 cuillère à soupe de fromage de chèvre et de 1 cuillère à soupe d'amandes effilées."],[],[]),
(6149915,"Chou-fleur rôti","Vous n'êtes pas un grand fan de légumes ? Essayez de les faire rôtir. Rôtir les légumes est l'un des moyens les plus faciles et les plus savoureux de les préparer.","6","1/2 tasse",
["1 pulvérisation, 0,25 g d'aérosol de cuisson antiadhésif","1 chou-fleur (coupé en petits bouquets)","2 cuillères à soupe d'huile d'olive","1/4 cuillère à café de poivre noir","1/4 cuillère à café de sel"],
["Préchauffez le four à 425 degrés F. Graissez une plaque de cuisson avec l'aérosol de cuisson.","Dans un petit bol, mélangez le chou-fleur, l'huile d'olive, le poivre noir et le sel. Versez le mélange sur la plaque de cuisson.","Faites cuire 15 à 20 minutes, jusqu'à ce que le bout des bouquets de chou-fleur soit légèrement doré et tendre."],[],[]),
])
